#!/usr/bin/env python3
"""Conservative source-preedge FADD busy join for both FENCE paths."""
from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[1];S=R/'pipeline/riscv-isa-sim-C12-composite-v1';O=R/'build/C12-composite-preparation-v1'
def edit(n,a,b):
 p=S/'riscv'/n;s=p.read_text();assert s.count(a)==1,(n,a[:80],s.count(a));p.write_text(s.replace(a,b))
edit('iris_timing_adapter.h','  void fadd_eg_tick(unsigned);','  void fadd_eg_tick(unsigned);\n  bool fadd_eg_fence_wait(unsigned,const insn_fetch_t&);\n  std::vector<bool>fadd_eg_prebusy_;')
edit('iris_timing_adapter.cc','  fadd_eg_pending_.resize(cores_.size());','  fadd_eg_prebusy_.resize(cores_.size());\n  fadd_eg_pending_.resize(cores_.size());')
edit('iris_timing_adapter.cc','void iris_timing_adapter::issue(unsigned hart, reg_t pc, const insn_fetch_t& fetch) {','void iris_timing_adapter::issue(unsigned hart, reg_t pc, const insn_fetch_t& fetch) {\n  // Source EXU busy is sampled before the last VRF-write edge, including\n  // the ordinary conservative FENCE path when there is no OPU tail.\n  if(profile_.empirical_fadd_eg&&fadd_eg_fence_wait(hart,fetch))throw iris_timing_wait{};')
edit('iris_fadd_eg_actor.inc',' auto result=fadd_eg_queues_[h].step(edge,input?std::optional<iris::rvv_fadd_source::Command>(input->command):std::nullopt);fadd_eg_last_edge_[h]=edge;',' auto result=fadd_eg_queues_[h].step(edge,input?std::optional<iris::rvv_fadd_source::Command>(input->command):std::nullopt);fadd_eg_last_edge_[h]=edge;\n // Scheduler state after step may already be empty while this source edge\n // still consumes the final writepipe slot. Preserve the actual preedge busy.\n fadd_eg_prebusy_[h]=result.vdq_before||result.iq_before||result.seq_before||std::any_of(result.pipe.begin(),result.pipe.end(),[](const auto&p){return bool(p);});')
p=S/'riscv/iris_fadd_eg_actor.inc';p.write_text(p.read_text()+'''\n// Independent readonly counters deliberately do not use this FENCE predicate.\nbool iris_timing_adapter::fadd_eg_fence_wait(unsigned h,const insn_fetch_t&fetch){\n if(h>=2)return false;auto i=fetch.insn;const auto raw=uint32_t(i.bits());\n if(i.length()!=4||(raw&0x707f)!=0x000f)return false;\n if(!fadd_eg_pending_[h].empty()||!fadd_eg_queues_[h].empty()||fadd_eg_clock_active_[h])return true;\n const auto d=profile_.harts[h].divider;const auto last=fadd_eg_last_edge_[h];\n if(last&&clock_.now()%d==0&&*last==clock_.now()/d&&fadd_eg_prebusy_[h]){\n  if(clock_.now()>UINT64_MAX-d)throw std::overflow_error("IRIS_FADD_EG_FENCE_EDGE_HORIZON");\n  opu_fence_retry_[h]=clock_.now()+d;return true;\n }\n return false;\n}\n''')
# Defense in depth: early MM-only FENCE cannot bypass a distinct FADD owner.\nedit('iris_opu_fence.inc',' if(!profile_.empirical_opu_fence||h>=2)return false;',' if(!profile_.empirical_opu_fence||h>=2)return false;\n if(profile_.empirical_fadd_eg&&fadd_eg_fence_wait(h,fetch))return false;')
files=['iris_timing_adapter.h','iris_timing_adapter.cc','iris_fadd_eg_actor.inc','iris_opu_fence.inc'];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();(O/'FADD-FENCE-join.json').write_text(json.dumps(dict(schema='iris.C12_composite_FADD_FENCE_join.v1',scope='ordinary FENCE only; both generic and MM-specialized paths; independent counters excluded',pending_and_full_controller_veto=True,preedge_final_write_busy_until_following_edge=True,no_new_write_or_retire_event=True,hardware_contacted=False,source_sha256={n:sha(S/'riscv'/n)for n in files}),indent=2)+'\n')
